e any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=SPLIT(saleorderitemcode, \'-\')[OFFSET(0)] left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from neshanka-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(d.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from neshanka-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) LEFT JOIN neshanka-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.product_category) UNION ALL SELECT cast(NULL AS string) customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, \'AMAZON IN\' AS marketplace, \'AMAZON IN\' AS CHANNEL, \'AMAZON IN\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL AS PHONE, afi.NAME, COALESCE(EEFI.EMAIL, UFI.EMAIL, AFI.EMAIL) AS EMAIL, COALESCE( CAST(EEFI.shipping_last_update_date AS timestamp), CAST(UFI.shipping_last_update_date AS timestamp) ) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, cast(afi.PRODUCT_ID as string) PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS datetime) Order_Time, afi.QUANTITY, IFNULL(TOTAL_SALES, 0) - IFNULL(coalesce(eefi.tax,afi.TAX), 0) + IFNULL(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, coalesce(eefi.tax,afi.TAX) tax, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(EEFI.order_status, UFI.order_status)) AS OMS_order_status, UPPER(COALESCE(EEFI.shipping_status, UFI.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_