pping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATE_DIFF(CAST(CURRENT_DATE() AS DATE), CAST(afi.ORDER_TIMESTAMP AS DATE), DAY) END AS Days_in_Shipment, NULL AS ACQUISITION_DATE, COALESCE(afi.SKU, UFI.PRODUCT_ID, EEFI.SKU) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(coalesce(cm.final_Category,AFI.PRODUCT_CATEGORY)) AS PRODUCT_CATEGORY, UPPER(AFI.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY ,CAST(AFI.commonsku AS STRING) AS commonsku ,UPPER(coalesce(EEFI.warehouse_name, UFI.warehouse_name)) AS WAREHOUSE, COALESCE(AFI.pincode, UFI.pincode, EEFI.pincode) AS pincode, coalesce(EEFI.pickup_pincode, fa.pincode) source_pincode ,null as discount_codes FROM neshanka-wh.maplemonk.neshanka_wh_AMAZON_USA_FACT_ITEMS AFI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM neshanka-wh.maplemonk.neshanka_wh_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) EEFI ON AFI.Order_id = EEFI.reference_code AND AFI.SKU = EEFI.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM neshanka-wh.maplemonk.neshanka_wh_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON cast(AFI.order_id as string) = cast(UFI.order_id as string) AND cast(AFI.product_id as string) = cast(UFI.PRODUCT_ID as string) left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from neshanka-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM neshanka-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) LEFT JOIN neshanka-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(afi.product_category) UNION ALL SELECT NULL AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.mapped_category)) AS PRODUCT_CATEGORY ,null AS PRODUCT_SUB_CATEGORY ,b.commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode ,null as discount_codes FROM neshanka-wh.maplemonk.neshanka_wh_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM neshanka-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN neshanka-wh.maplemonk.category_mapping cm on upper(cm.category) = upper(b.mapped_category) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\')) and reference_code not in (select distinct reference_code from neshanka-wh.maplemonk.neshanka_wh_unicommerce_fact_items) and UPPER(reference_code) NOT LIKE \'%STN%\' and not(upper(trim(customer_name)) like any (\'%AMAZON%\',\'PJTJ TECHNOLOGIES PRIVATE LIMITED\',\'%CLOUDKART VENTURES PRIVATE LIMITED%\',\'JUPITER KART PRIVATE LIMITED\',\'MOKSH ENTERPRISES PRIVATE LIMITED\', \'%MOONSTONE VENTURES LLP%\',\'%ASVAH%\',\'%CLOUDSTORE%\',\'%FLIPKART%\',\'%MOONSTONE%\',\'%NESHANKA%\',\'%KIRANAKART TECHNOLOGIES%\',\'ZEPTO PRIVATE LIMITED\',\'%PJTJ%\')) UNION ALL SELECT NULL AS customer_id, \'ZEPTO\' AS shop_name, \'ZEPTO\' AS marektplace, \'ZEPTO\' AS CHANNEL, \'ZEPTO\' AS SOURCE, order_item AS ORDER_ID, NULL AS reference_code, NULL AS PHONE, NULL AS NAME, NULL AS EMAIL, NULL AS SHIPPING_LAST_UPDATE_DATE, NULL AS SKU, NULL AS PRODUCT_ID, Product_name AS PRODUCT_NAME, NULL AS CURRENCY, CITY AS city, NULL AS State, NULL AS order_status, CAST(Order_Date AS date) AS Order_Date, NULL AS Order_Time, quantity AS QUANTITY, Gross_Selling_Value AS gross_sales_before_tax, NULL AS DISCOUNT, NULL AS TAX, NULL AS SHIPPING_PRICE, selling_price AS SELLING_PRICE, NULL AS OMS_ORDER_STATUS, NULL AS SHIPPING_STATUS, NULL AS FINAL_SHIPPING_STATUS, NULL AS SALEORDERITEMCODE, NULL AS SALES_ORDER_ITEM_ID, NULL AS AWB, NULL AS payment_gateway, NULL AS payment_mode, NULL AS COURIER, NULL AS DISPATCH_DATE, NULL AS delivered_date, NULL AS DELIVERED_STATUS, NULL AS RETURN_FLAG, NULL AS returned_quantity, NULL AS returned_sales, NULL AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, NULL AS days_in_shipment, NULL AS ACQUISITION_DATE, sku_number AS sku_code, Product_name AS PRODUCT_NAME_FINAL, sku_category AS PRODUCT_CATEGORY, sub_category AS PRODUCT_SUB_CATEGORY, NULL AS commonsku, NULL AS warehouse, NULL AS pincode, NULL AS source_pincode, NULL AS discount_codes FROM maplemonk.neshanka_zepto_fact_items UNION ALL SELECT NULL AS customer_id, \'SWIGGY\' AS shop_name, \'SWIGGY\' AS marektplace, \'SWIGGY\' AS CHANNEL, \'SWIGGY\' AS SOURCE, Campaign_ID AS ORDER_ID, NULL AS reference_code, NULL AS PHONE, NULL AS NAME, NULL AS EMAIL, NULL AS SHIPPING_LAST_UPDATE_DATE, NULL AS SKU, Campaign_ID AS PRODUCT_ID, Product_Name AS PRODUCT_NAME, NULL AS CURRENCY, NULL AS city, NULL AS State, NULL AS order_status, CAST(Date AS DATE) AS Order_Date, CAST(Date AS DATETIME) AS ORDER_TIME, NULL AS QUANTITY, SAFE_CAST(ad_sales AS FLOAT64) AS gross_sales_before_tax, NULL AS DISCOUNT, NULL AS TAX, NULL AS SHIPPING_PRICE, SAFE_CAST(spend AS FLOAT64) AS SELLING_PRICE, NULL AS OMS_ORDER_STATUS, NULL AS SHIPPING_STATUS, NULL AS FINAL_SHIPPING_STATUS, NULL AS SALEORDERITEMCODE, NULL AS SALES_ORDER_ITEM_ID, NULL AS AWB, NULL AS payment_gateway, NULL AS payment_mode, NULL AS COURIER, NULL AS DISPATCH_DATE, NULL AS delivered_date, NULL AS DELIVERED_STATUS, NULL AS RETURN_FLAG, NULL AS returned_quantity, NULL AS returned_sales, NULL AS cancelled_quantity, NULL AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, NULL AS days_in_shipment, NULL AS ACQUISITION_DATE, NULL AS sku_code, Product_Name AS PRODUCT_NAME_FINAL, NULL AS PRODUCT_CATEGORY, NULL AS PRODUCT_SUB_CATEGORY, NULL AS commonsku, NULL AS warehouse, NULL AS pincode, NULL AS source_pincode, NULL AS discount_codes FROM MAPLEMONK.Ritualistic_SWIGGY_SALES_FACT_ITEMS ; CREATE OR REPLACE TABLE neshanka-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM neshanka-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM neshanka-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN neshanka-wh.maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE neshanka-wh.maplemonk.neshanka_wh_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); create or replace table neshanka-wh.maplemonk.neshanka_wh_sales_consolidated as select final_marketplace, customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, RTO_flag, DTO_flag, RTO_value, DTO_value, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, cast(null as int64) as Original_Return_Value, cast(null as string) as Return_Reference_Code, \'Sale\' as TYPE, from maplemonk.neshanka_wh_sales_consolidated union all select cast(null as string) final_marketplace, null customer_id_final, null acquisition_date, null first_complete_order_date, null Order_Quantity, null RTO_flag, null DTO_flag, null RTO_value, null DTO_value, s.maple_monk_id_phone, s.customer_id, s.SHOP_NAME, s.marketplace, s.CHANNEL, s.SOURCE, null ORDER_ID, null reference_code, null PHONE, null NAME, null EMAIL, null SHIPPING_LAST_UPDATE_DATE, null SKU, null PRODUCT_ID, null PRODUCT_NAME, null CURRENCY, r.CITY, r.State, null ORDER_STATUS, return_date as Order_Date, null Order_Time, null QUANTITY, null GROSS_SALES_BEFORE_TAX, null DISCOUNT, null TAX, null SHIPPING_PRICE, null SELLING_PRICE, null OMS_order_status, null SHIPPING_STATUS, null FINAL_SHIPPING_STATUS, null SALEORDERITEMCODE, null SALES_ORDER_ITEM_ID, null AWB, null PAYMENT_GATEWAY, null Payment_Mode, null COURIER, null DISPATCH_DATE, null DELIVERED_DATE, null DELIVERED_STATUS, null RETURN_FLAG, null returned_quantity, null returned_sales, null cancelled_quantity, null Days_in_Shipment, null MARKETPLACE_ACQUISITION_DATE, null SKU_CODE, null PRODUCT_NAME_FINAL, null PRODUCT_CATEGORY, null PRODUCT_SUB_CATEGORY, null commonsku, null WAREHOUSE, null pincode, null source_pincode, null discount_codes, null new_customer_flag, null new_customer_flag_month, null acquisition_product, null acquisition_channel, null acquisition_marketplace, r.RETURN_AMOUNT as Original_Return_Value, r.reference_Code as Return_Reference_Code, \'Return\' as TYPE, from ( select ri.order_name reference_code, date(delivered_date) RETURN_DATE, sc.marketplace, ri.common_sku, sc.channel, sc.city, sc.state, sc.Payment_Mode, sc.PAYMENT_GATEWAY, return_amount from ( select concat(\'#\',SPLIT(channel_order_id, \'_\')[OFFSET(cast(is_return as int64))]) order_name, DATETIME(TIMESTAMP(nullif(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.delivered_date\') as string), \'\"\', \'\'), \'0000-00-00 00:00:00\' )), \'Asia/Kolkata\') delivered_date, \'WEBSITE\' as marketplace, REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.awb\') as string), \'\"\', \'\') awb, REPLACE(cast(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\') as string), \'\"\', \'\') AS common_SKU, cast(JSON_EXTRACT_SCALAR(P, \'$.product_cost\') as float64) AS RETURN_AMOUNT FROM `MAPLEMONK.Ritualistic_db_orders` left join UNNEST(SHIPMENTS) AS A left join UNNEST(products) AS P where lower(status) like any (\'%return%\',\'%rto%\',\'%pickup%\') Qualify row_number() over(partition by SPLIT(channel_order_id, \'_\')[OFFSET(cast(is_return as int64))] ,REPLACE(cast(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\') as string), \'\"\', \'\') order by updated_at desc) = 1 ) ri left join ( select reference_code, marketplace, channel, city, awb, state, Payment_Mode, PAYMENT_GATEWAY from MAPLEMONK.NESHANKA_WH_sales_consolidated qualify row_number() over(partition by reference_code order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.order_name,\'#\',\'\'))) UNION ALL ( select ri.reference_code, cast(ri.Return_initiated_date as Date) RETURN_DATE, sc.marketplace, SKU as common_SKU, sc.channel, city, state, Payment_Mode, PAYMENT_GATEWAY, Total_Credit_Note_Amount as RETURN_AMOUNT FROM maplemonk.easyecom_Neshanka_all_returns ri left join ( select reference_code, marketplace, channel, city, state, Payment_Mode, PAYMENT_GATEWAY from MAPLEMONK.NESHANKA_WH_sales_consolidated qualify row_number() over(partition by reference_code order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.reference_code,\'#\',\'\'))) where not(lower(ri.marketplace) like any (\'%amazon%\')) ) UNION ALL ( select ri.order_id, cast(ri.return_requested_at as date) return_requested_at, sc.marketplace as marketplace_New, merchant_SKU as common_SKU, channel, city, state, Payment_Mode, PAYMENT_GATEWAY, refunded_amount as RETURN_AMOUNT FROM maplemonk.neshanka_Amazon_IN_returns_fact_items ri left join ( select reference_code,marketplace,channel,city,state,Payment_Mode,PAYMENT_GATEWAY from MAPLEMONK.NESHANKA_WH_sales_consolidated qualify row_number() over(partition by reference_code order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.ordeR_id,\'#\',\'\'))) ) ) r left join maplemonk.neshanka_wh_Sales_consolidated s on s.reference_code = r.reference_Code and s.sku = r.common_SKU ; CREATE TABLE IF NOT EXISTS neshanka-wh.maplemonk.neshanka_wh_easyecom_returns_intermediate ( ORDER_ID INT64, INVOICE_ID INT64, SUBORDER_ID STRING, REFERENCE_CODE STRING, CREDIT_NOTE_ID INT64, ORDER_DATE TIMESTAMP, INVOICE_DATE TIMESTAMP, RETURN_DATE TIMESTAMP, MANIFEST_DATE TIMESTAMP, IMPORT_DATE TIMESTAMP, LAST_UPDATE_DATE TIMESTAMP, COMPANY_PRODUCT_ID STRING, PRODUCTNAME STRING, PRODUCT_ID STRING, SKU STRING, MARKETPLACE STRING, MARKETPLACE_ID INT64, REPLACEMENT_ORDER INT64, RETURN_REASON STRING, RETURNED_QUANTITY FLOAT64, RETURN_AMOUNT_WITHOUT_TAX FLOAT64, RETURN_TAX FLOAT64, RETURN_SHIPPING_CHARGE FLOAT64, RETURN_MISC FLOAT64, TOTAL_RETURN_AMOUNT FLOAT64 ); CREATE OR REPLACE TABLE neshanka-wh.maplemonk.neshanka_wh_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM neshanka-wh.maplemonk.neshanka_wh_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, Source FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE TABLE IF NOT EXISTS neshanka-wh.maplemonk.neshanka_wh_unicommerce_returns_intermediate ( MARKETPLACE STRING, SOURCE STRING, ORDER_ID STRING, REFERENCE_CODE STRING, PHONE STRING, NAME STRING, EMAIL STRING, ORDER_DATE TIMESTAMP, RETURN_DISPLAYCODE STRING, RETURN_STATUS STRING, INVENTORY_RECEIVED_DATE TIMESTAMP, RETURN_COMPLETE_DATE TIMESTAMP, RETURN_INVOICE_DISPLAY_CODE STRING, RETURN_COURIER STRING, RETURN_PROVIDER_SHIPPING_STATUS STRING, RETURN_TRACKING_NUMBER STRING, RETURN_TYPE STRING, sale_order_item_code STRING, ITEMSKU STRING, ITEM_NAME STRING, INVENTORY_TYPE STRING ); CREATE OR REPLACE TABLE neshanka-wh.maplemonk.neshanka_wh_unicommerce_returns_fact_items AS SELECT IFNULL(FE.channel, \'NA\') AS Marketing_CHANNEL, FE.quantity AS RETURNED_QUANTITY, FE.selling_price AS TOTAL_RETURN_AMOUNT, FE.tax AS RETURN_TAX, FE.selling_price - FE.tax AS RETURN_AMOUNT_WITHOUT_TAX, FR.* FROM (select * from neshanka-wh.maplemonk.neshanka_wh_unicommerce_returns_intermediate where RETURN_DISPLAYCODE is not null) FR LEFT JOIN ( SELECT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, SUM(quantity) AS quantity, SUM(selling_price) AS Selling_price, SUM(tax) AS tax FROM neshanka-wh.maplemonk.neshanka_wh_sales_consolidated GROUP BY REFERENCE_CODE, SALEORDERITEMCODE, channel, Source ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE AND FR.sale_order_item_code = FE.SALEORDERITEMCODE; CREATE OR REPLACE TABLE neshanka-wh.maplemonk.neshanka_wh_RETURNS_CONSOLIDATED AS SELECT CAST(er.Return_Date AS DATE) AS return_Date, UPPER(er.marketplace) AS Marketplace, COALESCE(sc.channel, er.marketplace) AS Marketing_channel, SUM(CAST(er.Returned_quantity AS INT64)) AS TOTAL_RETURNED_QUANTITY, SUM(CAST(er.Total_Credit_Note_Amount AS FLOAT64)) AS TOTAL_RETURN_AMOUNT, SUM(CAST(er.Total_Credit_Note_Amount AS FLOAT64)) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM maplemonk.easyecom_Neshanka_all_returns er LEFT JOIN ( SELECT channel, REPLACE(reference_code, \'#\', \'\') AS reference_code, saleorderitemcode FROM neshanka-wh.maplemonk.neshanka_wh_SALES_CONSOLIDATED ) sc ON er.reference_code = sc.reference_code AND er.saleorderitemcode = sc.saleorderitemcode WHERE UPPER(er.marketplace) NOT LIKE \'%AMAZON%\' AND UPPER(er.marketplace) NOT LIKE \'%B2B%\' GROUP BY CAST(er.Return_Date AS DATE), UPPER(er.marketplace), COALESCE(sc.channel, er.marketplace) UNION ALL SELECT CAST(return_delivery_date AS date) AS return_Date, UPPER(MARKETPLACE) AS Marketplace, \'AMAZON IN\' AS Marketing_channel, SUM(CAST(return_quantity AS INT64)) AS TOTAL_RETURNED_QUANTITY, SUM(CAST(refunded_amount AS FLOAT64)) AS TOTAL_RETURN_AMOUNT, SUM(CAST(refunded_amount AS FLOAT64)) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM maplemonk.neshanka_Amazon_IN_returns_fact_items GROUP BY Marketplace, RETURN_DATE, Marketing_channel UNION ALL UNION ALL SELECT date(delivered_date) RETURN_DATE, sc.marketplace, sc.marketing_channel, sc.quantity, ri.RETURN_AMOUNT, ri.RETURN_AMOUNT*0.88 as TOTAL_RETURN_AMOUNT_EXCL_TAX from ( select concat(\'#\',SPLIT(channel_order_id, \'_\')[OFFSET(cast(is_return as int64))]) order_name, DATETIME(TIMESTAMP(nullif(REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.delivered_date\') as string), \'\"\', \'\'), \'0000-00-00 00:00:00\' )), \'Asia/Kolkata\') delivered_date, \'WEBSITE\' as marketplace, REPLACE(cast(JSON_EXTRACT_SCALAR(A, \'$.awb\') as string), \'\"\', \'\') awb, REPLACE(cast(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\') as string), \'\"\', \'\') AS common_SKU, cast(JSON_EXTRACT_SCALAR(P, \'$.product_cost\') as float64) AS RETURN_AMOUNT FROM `MAPLEMONK.Ritualistic_db_orders` left join UNNEST(SHIPMENTS) AS A left join UNNEST(products) AS P where lower(status) like any (\'%return%\',\'%rto%\',\'%pickup%\') Qualify row_number() over(partition by SPLIT(channel_order_id, \'_\')[OFFSET(cast(is_return as int64))] ,REPLACE(cast(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\') as string), \'\"\', \'\') order by updated_at desc) = 1 ) ri left join ( select reference_code, marketplace, channel, city, awb, state, Payment_Mode, PAYMENT_GATEWAY from MAPLEMONK.NESHANKA_WH_sales_consolidated qualify row_number() over(partition by reference_code order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.order_name,\'#\',\'\'))) ;",
                    "transaction": true
                }
            ) }}
